import type { WriteKind } from "../../../core/mapper/MapperProfile";

/**
 * Every mapper path gen1 touches, from `docs/gen1-inventory.md` (generated by
 * `tools/parity/inventory.ts` on 2026-09-10 after the Phase 1 renames: 224 paths,
 * 36 of them written). Shared by both DEPRECATED gen1 profiles, because Yellow and
 * Red/Blue expose the same vocabulary.
 *
 * Keep this in step with the inventory, not the other way round: when a component
 * starts reading a new path, regenerate the inventory and add the path here, or the
 * canonical view will hand that component `undefined`.
 *
 * Six entries are containers rather than leaves (`battle`, `battle.enemyPokemon`,
 * `battle.yourPokemon`, `patch.encounter_flags`, `player.badges`, `player.team.0`).
 * They are what components index dynamically -- `badges['badge' + x]`,
 * `battle[side][stat]` -- and the adapter aliases them to the mapper's real objects so
 * the children the static inventory cannot see stay reachable.
 *
 * 36 of the declared keys do not exist in either shipped mapper file -- the
 * `patch.battle_info.hits.*` and `.turns.hits.*` counters the Full CSV writer reads.
 * The legacy code reads every one of them optional-chained with a `?? 0` default, so
 * they were `undefined` on the raw tree and are `undefined` on the view; declaring them
 * records that the overlay *asks*, which is what a future mapper would have to supply.
 * `npm run parity:adapter` lists them.
 */
